corrected_code:
const express = require('express');
const { Pool } = require('pg');
const { verifyUserToken } = require('../auth');

const app = express();
const db = new Pool({ connectionString: process.env.PG_SESSION_URL });

app.get('/api/users/:userId/active-devices', verifyUserToken, async (req, res) => {
  const { userId } = req.params;

  // Ensure user can only inspect their own device sessions
  if (req.user.id !== userId && !req.user.isSecurityAuditor) {
    return res.status(403).json({ error: 'Access denied: cannot inspect active devices of another user' });
  }

  const query = `
    SELECT sid, expire, sess->'ipAddress' AS ip, sess->'userAgent' AS agent, sess->'lastActive' AS last_seen
    FROM "session"
    WHERE sess->'user'->>'id' = $1 AND expire > NOW()
  `;
  const { rows } = await db.query(query, [userId]);

  res.json({ userId, activeSessions: rows });
});

app.listen(8098);
